{
  "target_qa_variants": [
    {
      "language": "en",
      "variant_layer": "core",
      "question": "What is the first live-action television series in the Star Wars franchise?",
      "expected_answer": "The Mandalorian",
      "answer_aliases": [
        "Mandalorian"
      ],
      "rewrite_note": "direct core question"
    },
    {
      "language": "en",
      "variant_layer": "surface",
      "question": "Which 2019 live-action TV show was the first released for the Star Wars franchise?",
      "expected_answer": "The Mandalorian",
      "answer_aliases": [
        "Mandalorian"
      ],
      "rewrite_note": "includes release year and focuses on the 'first released' aspect"
    },
    {
      "language": "en",
      "variant_layer": "surface",
      "question": "Name the inaugural live-action Star Wars series that debuted in 2019.",
      "expected_answer": "The Mandalorian",
      "answer_aliases": [
        "Mandalorian"
      ],
      "rewrite_note": "uses 'inaugural' and 'debuted' as synonyms"
    },
    {
      "language": "en",
      "variant_layer": "surface",
      "question": "What is the title of the first live-action series set in the Star Wars universe?",
      "expected_answer": "The Mandalorian",
      "answer_aliases": [
        "Mandalorian"
      ],
      "rewrite_note": "rephrases 'franchise' to 'universe' and asks for the title"
    }
  ],
  "neighbor_qa_variants": [
    {
      "language": "en",
      "variant_layer": "core",
      "question": "Which Star Trek spinoff series follows the crew of a new starship Enterprise a century after the original series?",
      "expected_answer": "The Next Generation",
      "answer_aliases": [
        "Star Trek: The Next Generation",
        "TNG"
      ],
      "rewrite_note": "direct core question"
    },
    {
      "language": "en",
      "variant_layer": "surface",
      "question": "What is the name of the Star Trek series set one hundred years after the original, featuring a new Enterprise crew?",
      "expected_answer": "The Next Generation",
      "answer_aliases": [
        "Star Trek: The Next Generation",
        "TNG"
      ],
      "rewrite_note": "changes 'a century' to 'one hundred years' and restructures the sentence"
    },
    {
      "language": "en",
      "variant_layer": "surface",
      "question": "Name the Star Trek television spinoff that takes place a century after the events of the original series.",
      "expected_answer": "The Next Generation",
      "answer_aliases": [
        "Star Trek: The Next Generation",
        "TNG"
      ],
      "rewrite_note": "uses imperative 'Name the' and simplifies the description"
    },
    {
      "language": "en",
      "variant_layer": "surface",
      "question": "Which TV series in the Star Trek franchise focuses on a new starship Enterprise crew a century later?",
      "expected_answer": "The Next Generation",
      "answer_aliases": [
        "Star Trek: The Next Generation",
        "TNG"
      ],
      "rewrite_note": "uses 'focuses on' and 'a century later' for variety"
    }
  ]
}
